#include "gmm_params.h"

#include "andon_gmm.h"  // generated by andon.export_gmm into firmware/model (not in git)

_Static_assert(ANDON_GMM_N_FANS == 3, "gmm_params.c lists three fans");
_Static_assert(ANDON_GMM_N_DIM <= GMM_MAX_DIM, "raise GMM_MAX_DIM");
_Static_assert(ANDON_GMM_N_COMPONENTS <= GMM_MAX_COMPONENTS, "raise GMM_MAX_COMPONENTS");
_Static_assert(ANDON_GMM_WINDOW_FRAMES == 2 * ANDON_GMM_WINDOW_HOP,
               "gmm_window_t keeps two half-window sums");

#define PER_FAN (ANDON_GMM_N_COMPONENTS * ANDON_GMM_N_DIM)
#define FAN(f)                                                         \
    {                                                                  \
        .n_components = ANDON_GMM_N_COMPONENTS, .n_dim = ANDON_GMM_N_DIM, \
        .mean = &andon_gmm_mean[(f) * PER_FAN],                        \
        .chol = &andon_gmm_chol[(f) * ANDON_GMM_N_COMPONENTS * ANDON_GMM_N_TRI], \
        .log_const = &andon_gmm_log_const[(f) * ANDON_GMM_N_COMPONENTS], \
    }

const int andon_gmm_n_fans = ANDON_GMM_N_FANS;
const int andon_gmm_window_hop = ANDON_GMM_WINDOW_HOP;
const gmm_t andon_gmm[ANDON_GMM_N_FANS] = {FAN(0), FAN(1), FAN(2)};
const char *const *const andon_gmm_fan_ids = andon_gmm_fan_id;
const char *const andon_gmm_model_source = andon_gmm_source;
